"""Service mode 'Administer Linac' functions. These functions are called from the top level
IntegrityService interface. They are not intended to be called directly from a test script"""

import interops.libraries.integrity.integrity_objects as IntegrityObjects
import interops.libraries.integrity.pages.common_menu_bars as CommonMenuPgObj
import interops.libraries.integrity.pages.service_screen as ServicePgObj
from interops.libraries.miscellaneous.registry_functions import getRegistryValue_cmd_version
from interops.libraries.desktop.configuration import Config
import interops.libraries.desktop.config_constants as cfg
import interops.libraries.desktop.decorators as deco
from interops.libraries.squish_actions.constants import INTEGRITY_APP_NAME
import sys, os
import squishtest3 as sq
import logging


logger = logging.getLogger(__name__)

@deco.set_separate_app_context(INTEGRITY_APP_NAME)
def _admin_enable_clinical_mode(enabled: bool=True) -> bool:
    '''
    Enables or disables clinical mode when logged in as service mode
    Checks the registry key for a value of 1 for input True and 0 for input False

    Args:
        enabled (bool): True for enabling or False for disabling clinical mode

    Returns:
        bool: True if function correctly disabled/enabled clinical mode according to input
    '''
    try:
        # Get the current python installation path
        python_install_path = sys.exec_prefix
        sharedconfig_path = os.path.abspath(os.path.join(
            python_install_path, cfg.DEFAULT_SHAREDCONFIG_PATH))
        # Load the sharedconfig.cfg file
        Config.load(sharedconfig_path)

        service_menu = ServicePgObj.ServiceMenuBar()
        service_menu.admin_linac()
        sq.snooze(1)
        if enabled:
            service_menu.enable_clinical_mode()
        else:
            service_menu.disable_clinical_mode()
        sq.mouseClick(sq.waitForObject(IntegrityObjects.yes_Button, 2000))
        # TODO - Consider using credentials from sharedconfig.cfg as per previous implementation, so these can be updated in one place
        _admin_confirm_password("service")
        sq.snooze(3)
        if enabled:
            return getRegistryValue_cmd_version(
                r"SOFTWARE\Elekta Oncology Systems Ltd\Linac",
                "ClinicalUse",
                host=Config.get("attach.host"),
                port=Config.get("attach.port")).strip("\n") == "1"
        return getRegistryValue_cmd_version(
            r"SOFTWARE\Elekta Oncology Systems Ltd\Linac",
            "ClinicalUse",
            host=Config.get("attach.host"),
            port=Config.get("attach.port")).strip("\n") != "1"
    except Exception as e:
        logger.info("Failed to enable clinical mode " + str(e))
        return False


@deco.set_separate_app_context(INTEGRITY_APP_NAME)
def _admin_confirm_password(password: str) -> bool:
    try:
        CommonMenuPgObj.set_edit_box(IntegrityObjects.verify_password, password)
        sq.mouseClick(IntegrityObjects.verify_user_details_ok)
        return True
    except Exception:
        return False


@deco.set_separate_app_context(INTEGRITY_APP_NAME)
def _admin_enable_energies() -> bool:
    '''
    Enables all energies via the Administrator Linac menu in service mode

    Returns:
        bool - True if energies enabled suceeded
    '''
    try:
        service_menu = ServicePgObj.ServiceMenuBar()
        service_menu.admin_linac()
        sq.snooze(1)
        service_menu.enable_energies()
        for energy_type in ["   X-Rays   ", "   Electron   "]:
            sq.mouseClick(sq.waitForObject({"text": energy_type}))
            sq.snooze(1)
            if energy_type == "   X-Rays   ":
                if sq.object.children(sq.waitForObject({"id": "DisabledXRayEnergiesListBox"})) == ():
                    continue
                else:
                    sq.keyPress("<Ctrl>")
                    for energy in sq.object.children(sq.waitForObject({"id": "DisabledXRayEnergiesListBox"})):
                        sq.mouseClick(energy)
                        sq.snooze(1)
                    sq.mouseClick(sq.waitForObject({"text": "Enable"}))
                    sq.keyRelease("<Ctrl>")
            elif energy_type == "   Electron   ":
                if sq.object.children(sq.waitForObject({"id": "DisabledElectronEnergiesListBox"})) == ():
                    continue
                else:
                    sq.keyPress("<Ctrl>")
                    for energy in sq.object.children(sq.waitForObject({"id": "DisabledElectronEnergiesListBox"})):
                        sq.mouseClick(energy)
                        sq.snooze(1)
                    sq.mouseClick(sq.waitForObject({"text": "Enable"}))
                    sq.keyRelease("<Ctrl>")
        try:
            sq.mouseClick(sq.waitForObject({"text": "Save"}, 2000))
            sq.snooze(1)
        except Exception as e:
            logger.info("Save button not enabled or reason is " + str(e))
        return True
    except Exception as e:
        logger.info("Exception " + str(e))
        return False